/* ---------- Currency converter ---------- */
.ccx{padding:16px;display:flex;flex-direction:column;gap:6px;max-width:340px;margin:0 auto;width:100%;position:relative}
.ccx-row{display:flex;align-items:center;gap:8px;padding:10px 10px 10px 14px;border-radius:14px;background:var(--chip);transition:box-shadow .25s,background .25s}
/* the row rings when its amount field has the focus; its currency button rings on its own */
.ccx-row:has(.ccx-a:focus-visible){background:var(--surface);box-shadow:inset 0 0 0 2px var(--focus)}
.ccx-in{flex:1;display:flex;flex-direction:column;min-width:0;font-size:11.5px}
.ccx-a,.ccx-b{border:0;outline:0;background:transparent;font:inherit;font-size:14px;font-weight:500;letter-spacing:-.02em;color:var(--fg);padding:0;width:100%;min-width:0}
.ccx-cur{display:flex;align-items:center;gap:6px;height:34px;padding:0 10px;border-radius:10px;background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.06);font-size:13px;font-weight:500}
.ccx-cur .cd{font-family:var(--mono);font-size:12px}
.ccx-sw{align-self:center;width:32px;height:32px;margin:-16px 0;z-index:1;border-radius:50%;background:var(--surface);box-shadow:var(--shadow),0 0 0 4px var(--surface);display:grid;place-items:center;color:var(--fg2);transition:transform .5s var(--ease),color .2s}
@media (hover:hover) and (pointer:fine){.ccx-sw:hover{color:var(--fg)}}
.ccx-sw.go{transform:rotate(180deg)}
.ccx-rate{font-size:12px;text-align:center;margin-top:4px;display:flex;align-items:center;justify-content:center;gap:6px}
.ccx-rate .dot{color:var(--ok);animation:ccpulse 2s ease-in-out infinite}
@keyframes ccpulse{50%{opacity:.4}}
.ccx .pop{min-width:180px}
.ccx .mi .cd{font-family:var(--mono);font-size:11.5px;color:var(--muted);width:32px}

DM.def('currency-converter', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{chev\}/g, I('chev-d','xs')).replace('{swap}', I('sort','xs'));
  const RATE = { USD:1, EUR:.92, GBP:.79, JPY:149.6, CAD:1.37, AUD:1.52 };
  const NAME = { USD:'US dollar', EUR:'Euro', GBP:'Pound', JPY:'Yen', CAD:'Canadian dollar', AUD:'Australian dollar' };
  const SYM = { USD:'$', EUR:'€', GBP:'£', JPY:'¥', CAD:'C$', AUD:'A$' };
  let A = 'USD', B = 'EUR', out = 0;
  const a = $('.ccx-a', r), b = $('.ccx-b', r), rate = $('.ccx-rate', r), curs = $$('.ccx-cur', r);
  function calc(delay){ const n = parseFloat(a.value.replace(/[^\d.]/g, '')) || 0; const v = n / RATE[A] * RATE[B]; const dp = B === 'JPY' ? 0 : 2;
    const go = () => tween(out, v, 450, x => { out = x; b.textContent = SYM[B] + x.toLocaleString('en-US', { minimumFractionDigits:dp, maximumFractionDigits:dp }); }); delay ? c.later(delay, go) : go();
    rate.innerHTML = `<span class="dot"></span>1 ${A} = ${(RATE[B] / RATE[A]).toFixed(B === 'JPY' || A === 'JPY' ? 4 : 4)} ${B} · updated 2 min ago`; }
  function menus(){ [['.ccx-p1', 0], ['.ccx-p2', 1]].forEach(([sel, side]) => { const p = $(sel, r), cur = side ? B : A;
    p.innerHTML = Object.keys(RATE).map(k => `<button class="mi" data-close data-k="${k}" aria-checked="${k === cur}"><span class="cd">${k}</span><span>${NAME[k]}</span><span class="ck">${I('check','xs')}</span></button>`).join('');
    $$('.mi', p).forEach(m => m.addEventListener('click', () => { if (side) B = m.dataset.k; else A = m.dataset.k; if (A === B){ if (side) A = Object.keys(RATE).find(x => x !== B); else B = Object.keys(RATE).find(x => x !== A); } paint(); })); }); }
  function paint(delay){ swap($('.cd', curs[0]), A); swap($('.cd', curs[1]), B); menus(); calc(delay); }
  a.oninput = () => { a.value = a.value.replace(/[^\d.]/g, ''); calc(); };
  a.onblur = () => { const n = parseFloat(a.value) || 0; a.value = n.toFixed(2); };
  const sw = $('.ccx-sw', r);
  sw.onclick = () => { sw.classList.toggle('go'); const n = out; [A, B] = [B, A]; a.value = (B === 'JPY' || A === 'JPY') ? (A === 'JPY' ? Math.round(n) : n.toFixed(2)) : n.toFixed(2); a.value = String(a.value); paint(); };
  paint(260);
  // once in view it converts a new amount, then swaps the two currencies. Clicking, focusing or typing in it takes over
  c.run(async () => {
    await c.step(1500);
    await c.type(a, '120', { ms:150, each:() => calc(), clear:true });
    await c.step(250); a.value = '120.00';
    await c.step(1300); sw.click();
  });
});
